        @keyframes action-button-press-release { 0%{transform:scale(1);filter:brightness(1);box-shadow:2px 2px 3px var(--button-shadow-color)} 20%{transform:scale(1.02,0.92);filter:brightness(.85);box-shadow:inset 0 2px 4px rgba(0,0,0,.2)} 60%{transform:scale(.98,1.06);filter:brightness(1.05);box-shadow:3px 3px 5px var(--button-shadow-color)} 100%{transform:scale(1);filter:brightness(1);box-shadow:2px 2px 3px var(--button-shadow-color)} }
        .action-button:active { animation: action-button-press-release 0.35s ease-out forwards; }
