        .modal-overlay { position: fixed; top: 0; left: 0; width: 100%; height: 100%; background-color: rgba(0, 0, 0, 0.5); backdrop-filter: blur(4px); -webkit-backdrop-filter: blur(4px); display: flex; justify-content: center; align-items: center; z-index: 1000; opacity: 0; transition: opacity 0.25s ease; pointer-events: none; }
        .modal-overlay:not(.hidden) { opacity: 1; pointer-events: auto; }
        .confirm-dialog { background: var(--custom-bg); border: var(--custom-border); border-radius: var(--border-radius); padding: 30px; width: 90%; max-width: 450px; box-shadow: 0 6px 18px rgba(0, 0, 0, 0.15); opacity: 0; transform: scale(0.95); transition: opacity 0.25s ease, transform 0.25s ease; }
        .modal-overlay:not(.hidden) .confirm-dialog { opacity: 1; transform: scale(1); }
        .confirm-dialog h4 { color: var(--custom-text); margin-top: 0; margin-bottom: 18px; font-family: var(--font-main); text-align: center; font-size: 20px; }
        .confirm-dialog p { margin-bottom: 25px; line-height: 1.7; text-align: center; font-size: 15px; color: var(--custom-text); font-family: var(--font-main); }
        .dialog-buttons { display: flex; justify-content: space-between; gap: 10px; }
        .dialog-button { flex-grow: 1; padding: 10px 15px; border-radius: var(--border-radius); cursor: pointer; transition: background-color 0.2s ease, transform 0.2s ease, filter 0.2s ease, box-shadow 0.2s ease; border: 1px solid transparent; font-family: var(--font-main); font-size: 15px; font-weight: bold; text-align: center; box-shadow: 1px 1px 2px var(--button-shadow-color); text-shadow: 1px 1px 1px rgba(0,0,0,0.2); }
        @keyframes dialog-button-press-release { 0%{transform:scale(1);filter:brightness(1);box-shadow:1px 1px 2px var(--button-shadow-color)} 20%{transform:scale(1.02,0.92);filter:brightness(.85);box-shadow:inset 0 1px 3px rgba(0,0,0,.15)} 60%{transform:scale(.98,1.06);filter:brightness(1.05);box-shadow:2px 2px 4px var(--button-shadow-color)} 100%{transform:scale(1);filter:brightness(1);box-shadow:1px 1px 2px var(--button-shadow-color)} }
        .dialog-button:active { animation: dialog-button-press-release 0.35s ease-out forwards; }
        .cancel-button { background-color: var(--action-red); color: var(--action-text); border-color: var(--action-red-dark); }
        .cancel-button:hover { background-color: var(--action-red-dark); transform: translateY(-1px); box-shadow: 2px 2px 4px var(--button-shadow-color); }
        .confirm-button { background-color: var(--action-green); color: var(--action-text); border-color: var(--action-green-dark); }
        .confirm-button:hover { background-color: var(--action-green-dark); transform: translateY(-1px); box-shadow: 2px 2px 4px var(--button-shadow-color); }
        .dialog-button i { margin-right: 6px; font-size: 15px; vertical-align: -2px; color: var(--action-text); text-shadow: none;}
        .purchase-button { background-color: #5a9c5a; color: var(--action-text); border-color: #4a8c4a; }
        .purchase-button:hover { background-color: #4a8c4a; transform: translateY(-1px); box-shadow: 2px 2px 4px var(--button-shadow-color); }

        /* 自定义文本输入框样式 */
        .custom-input-container {
            margin-bottom: 20px;
        }
        .custom-input-title {
            font-size: 15px;
            margin-bottom: 8px;
            color: var(--custom-text);
            display: flex;
            align-items: center;
        }
        .custom-input-title i {
            margin-right: 8px;
            color: var(--custom-icon-blue);
        }
        .custom-text-input {
            width: 100%;
            padding: 10px 15px;
            font-family: var(--font-main);
            font-size: 14px;
            color: var(--custom-text);
            background: var(--custom-bg);
            border: 1px solid var(--custom-border-light);
            border-radius: var(--border-radius);
            box-sizing: border-box;
            transition: border-color 0.2s ease, box-shadow 0.2s ease;
        }
        .custom-text-input:focus {
            border-color: var(--custom-border-dark);
            outline: none;
            box-shadow: 0 0 0 2px rgba(140, 120, 93, 0.2);
        }
        .custom-text-input::placeholder {
            color: var(--custom-text-highlight);
            opacity: 0.7;
        }

        .hidden { display: none !important; }
        /* Responsive styles */
        @media (max-width: 700px) { body { font-size: 14px; padding: 10px;} .map-interface { padding: 20px; } .location-grid { grid-template-columns: repeat(2, 1fr); gap: 15px; margin-bottom: 25px;} .sub-location-grid { grid-template-columns: repeat(auto-fill, minmax(130px, 1fr)); gap: 12px; margin-bottom: 25px;} .character-list { grid-template-columns: repeat(auto-fill, minmax(120px, 1fr)); gap: 10px; } .location-button, .sub-location-button, .stardew-pixel-button { font-size: 14px; padding: 10px 14px; } .character-item { font-size: 13px; padding: 10px;} .action-button { font-size: 15px; padding: 10px 30px; } .dialog-button { font-size: 14px; padding: 8px 18px;} .confirm-dialog { padding: 25px; max-width: 90%;} .map-header h2 { font-size: 20px; } .detail-header { font-size: 17px; } .section-title { font-size: 15px; } .confirm-dialog h4 { font-size: 18px; } .confirm-dialog p { font-size: 14px; } }
        @media (max-width: 480px) { body { font-size: 13px; padding: 8px;} .map-interface { padding: 15px; margin: 8px auto; } .location-grid { grid-template-columns: repeat(2, 1fr); /* Keep 2 columns on small screens */ gap: 10px; margin-bottom: 20px;} .sub-location-grid { grid-template-columns: repeat(auto-fill, minmax(110px, 1fr)); gap: 10px; margin-bottom: 20px;} .character-list { grid-template-columns: repeat(2, 1fr); gap: 8px; } .location-button, .sub-location-button, .stardew-pixel-button { font-size: 13px; padding: 8px 12px; } .character-item { font-size: 12px; padding: 8px;} .action-button { font-size: 14px; padding: 9px 25px; } .dialog-button { font-size: 13px; padding: 7px 15px;} .confirm-dialog { padding: 20px;} .map-header h2 { font-size: 18px; } .detail-header { font-size: 16px; } .section-title { font-size: 14px; } .confirm-dialog h4 { font-size: 17px; } .confirm-dialog p { font-size: 13px; } .dialog-buttons { flex-direction: column; gap: 10px; } }

    </style>
</head>
<body>
    <!-- Data Source DIV (Hidden) -->
    <div id="map-data-source" style="display:none;"></div>

    <!-- Map Interface -->
    <div class="map-interface">
        <div class="map-header">
            <h2 id="map-title">风临镇地图</h2>
        </div>

        <!-- Movement Alert (Hidden) -->
        <div id="movement-alert" class="movement-alert hidden">
            <i class="fas fa-exclamation-triangle"></i> 提示：你现在无法移动
        </div>

        <!-- Main Locations (Buttons generated by JS - JS ADDS .stardew-pixel-button class) -->
        <div id="main-locations" class="location-grid"></div>

        <!-- Sub Locations (Buttons generated by JS - JS ADDS .stardew-pixel-button class) -->
        <div id="sub-locations" class="sub-location-grid hidden"></div>

        <!-- Location Details -->
        <div id="location-details" class="location-details hidden">
            <div class="detail-header">
                <i class="fas fa-map-marker-alt"></i> <span id="selected-location">未选择</span>
            </div>
            <div class="detail-content">
                <div class="character-section">
                    <div class="section-title"><i class="fas fa-user-friends"></i> 30分钟后该地点的人</div>
                    <div id="location-characters" class="character-list"></div>
                </div>
            </div>

            <!-- 新增的自定义文本输入框 -->
            <div class="custom-input-container">
                <div class="custom-input-title">
                    <i class="fas fa-comment"></i> 在该地点想要做什么
                </div>
                <input type="text" id="custom-message" class="custom-text-input" placeholder="输入你抵达此处后的行动计划...">
            </div>

            <div class="action-section">
                 <!-- Action Button (Uses its own style/animation) -->
                <button id="confirm-move-btn" class="action-button">
                    <i class="fas fa-walking"></i> 前往此处
                </button>
            </div>
        </div>
    </div>

    <!-- Confirmation Modal -->
    <div id="confirm-overlay" class="modal-overlay hidden">
        <div class="confirm-dialog">
            <h4>确认前往</h4>
            <p id="confirm-message"></p>
            <div class="dialog-buttons">
                 <!-- Dialog Buttons (Use their own style/animation) -->
                <button id="cancel-move-btn" class="dialog-button cancel-button">
                    <i class="fas fa-times"></i> 再想想
                </button>
                <button id="execute-move-btn" class="dialog-button confirm-button">
                    <i class="fas fa-check"></i> 出发吧
                </button>
                <button id="purchase-move-btn" class="dialog-button purchase-button">
                    <i class="fas fa-shopping-cart"></i> 前往购买
                </button>
            </div>
        </div>
    </div>

<script>
    // Global variables
    let currentMapData = null;
    let selectedMain = null;
    let selectedSub = null;
    let selectedCharacters = [];
    let isSpecialLocation = false; // 新增标记是否为特殊地点

    // 更新为风临镇的地图结构
    const fixedMapStructureDefinition = {
        locations: [
            { name: "城镇入口区", subLocations: [ { name: "风临镇大门", characters: [] }, { name: "陆行鸟厩", characters: [] } ]},
            { name: "中央商业区", subLocations: [ { name: "风临集市", characters: [] }, { name: "风铃旅店", characters: [] }, { name: "工匠街", characters: [] } ]},
            { name: "娱乐区", subLocations: [ { name: "金碟游乐场", characters: [] }, { name: "陆行鸟赛场", characters: [] }, { name: "陆行鸟厩舍", characters: [] } ]},
            { name: "住宅与管理区", subLocations: [ { name: "居民住宅区", characters: [] }, { name: "小广场/喷泉", characters: [] }, { name: "风临镇教堂", characters: [] } ]},
            { name: "城镇外围", subLocations: [ { name: "河边", characters: [] } ]},
            { name: "其他区域", subLocations: [ { name: "悠谷村", characters: [] } ]} // 保留悠谷村作为特殊地点
        ]
    };

    // Parse map data - 增强版，修改以适应新的地图结构
    function parseMapData(text) {
        // 检查输入
        if (!text || typeof text !== 'string' || text.includes('Set-Cookie:') || text.includes('<!DOCTYPE html>')) {
            console.warn("无效的地图数据，使用默认数据");
            text = "[]\n[]\n[]\n[]\n[]\n[]"; // 六个空数组，对应六个区域
        }

        // 创建基于固定结构的地图数据副本
        const populatedMapData = JSON.parse(JSON.stringify(fixedMapStructureDefinition));

        try {
            // 匹配所有方括号块
            const dataBlocks = text.match(/\[[^\]]*\]/gs) || [];
            let mainLocationIndex = 0;

            for (const block of dataBlocks) {
                // 跳过不包含 '-' 的块
                if (!block.includes('-')) {
                    mainLocationIndex++;
                    continue;
                }

                // 防止索引越界
                if (mainLocationIndex >= populatedMapData.locations.length) break;

                const currentMainLocation = populatedMapData.locations[mainLocationIndex];

                // 提取以 '-' 开头的行
                const lines = block.slice(1, -1).split('\n')
                    .map(l => l.trim())
                    .filter(l => l.startsWith('-'));

                let subLocationIndex = 0;

                for (const line of lines) {
                    // 防止索引越界
                    if (subLocationIndex >= currentMainLocation.subLocations.length) break;

                    const charactersText = line.substring(1).trim();
                    const characters = charactersText.split(',')
                        .map(c => c.trim())
                        .filter(c => c);

                    currentMainLocation.subLocations[subLocationIndex].characters = characters;
                    subLocationIndex++;
                }

                mainLocationIndex++;
            }

            return populatedMapData;
        } catch (e) {
            console.error("解析地图数据时出错:", e);
            return populatedMapData; // 返回默认数据结构
        }
    }

    // Render map interface - 更新图标以匹配风临镇主题
    function renderMapInterface(mapDataToRender) {
        if (!mapDataToRender) return;
        const movementAlert = document.getElementById('movement-alert'); 
        if (movementAlert) movementAlert.classList.add('hidden');

        const mainLocationsContainer = document.getElementById('main-locations'); 
        mainLocationsContainer.innerHTML = '';

        mapDataToRender.locations.forEach(location => {
            const button = document.createElement('button'); 
            button.className = 'location-button stardew-pixel-button'; // Use pixel class

            let icon = 'fa-map'; 
            if (location.name.includes('入口')) icon = 'fa-door-open'; // 入口区图标
            else if (location.name.includes('商业')) icon = 'fa-store'; // 商业区图标
            else if (location.name.includes('娱乐')) icon = 'fa-dice'; // 娱乐区图标
            else if (location.name.includes('住宅')) icon = 'fa-home'; // 住宅区图标
            else if (location.name.includes('外围')) icon = 'fa-tree'; // 城镇外围图标
            else if (location.name.includes('其他')) icon = 'fa-globe'; // 其他区域使用地球图标

            button.innerHTML = `<i class="fas ${icon}"></i> ${location.name}`; 
            button.dataset.location = location.name;

            button.addEventListener('click', () => selectMainLocation(button, location)); // Pass button
            mainLocationsContainer.appendChild(button);
        });

        resetSelectionVisuals();
    }

    // Select main location - 更新子地点图标
    function selectMainLocation(clickedButton, location) {
        selectedMain = location; 
        selectedSub = null; 
        selectedCharacters = [];
        isSpecialLocation = false; // 重置特殊地点标记

        document.querySelectorAll('#main-locations .location-button').forEach(btn => { 
            btn.classList.toggle('pixel-pressed', btn === clickedButton); 
        });

        const subLocationsContainer = document.getElementById('sub-locations'); 
        subLocationsContainer.innerHTML = '';

        location.subLocations.forEach(subLocation => {
            const button = document.createElement('button'); 
            button.className = 'sub-location-button stardew-pixel-button'; // Use pixel class

            let icon = 'fa-map-pin'; 

            // 风临镇专用图标
            if (subLocation.name.includes('大门')) icon = 'fa-archway';
            else if (subLocation.name.includes('陆行鸟厩')) icon = 'fa-feather-alt';
            else if (subLocation.name.includes('集市')) icon = 'fa-shopping-cart';
            else if (subLocation.name.includes('旅店')) icon = 'fa-bed';
            else if (subLocation.name.includes('工匠')) icon = 'fa-hammer';
            else if (subLocation.name.includes('游乐场')) icon = 'fa-gamepad';
            else if (subLocation.name.includes('赛场')) icon = 'fa-flag-checkered';
            else if (subLocation.name.includes('厩舍')) icon = 'fa-horse';
            else if (subLocation.name.includes('住宅')) icon = 'fa-house-user';
            else if (subLocation.name.includes('广场') || subLocation.name.includes('喷泉')) icon = 'fa-water';
            else if (subLocation.name.includes('教堂')) icon = 'fa-church';
            else if (subLocation.name.includes('河边')) icon = 'fa-water';
            else if (subLocation.name.includes('悠谷')) icon = 'fa-city'; // 悠谷村保持原样

            button.innerHTML = `<i class="fas ${icon}"></i> ${subLocation.name}`; 
            button.dataset.sublocation = subLocation.name;

            button.addEventListener('click', () => selectSubLocation(button, subLocation)); // Pass button
            subLocationsContainer.appendChild(button);
        });

        document.querySelectorAll('#sub-locations .sub-location-button.pixel-pressed').forEach(btn => { 
            btn.classList.remove('pixel-pressed'); 
        });

        subLocationsContainer.classList.remove('hidden'); 
        document.getElementById('location-details').classList.add('hidden');
    }

    // Select sub location - 检查是否为特殊地点
    function selectSubLocation(clickedButton, subLocation) {
        selectedSub = subLocation; 
        selectedCharacters = subLocation.characters || [];

        // 检查是否为悠谷村
        isSpecialLocation = subLocation.name === "悠谷村";

        document.querySelectorAll('#sub-locations .sub-location-button').forEach(btn => { 
            btn.classList.toggle('pixel-pressed', btn === clickedButton); 
        });

        document.getElementById('selected-location').textContent = `${selectedMain.name} - ${subLocation.name}`;

        const charactersContainer = document.getElementById('location-characters'); 
        charactersContainer.innerHTML = '';

        // 为悠谷村显示特殊提示
        if (isSpecialLocation) {
            const ne = document.createElement('div'); 
            ne.className = 'character-item empty'; 
            ne.innerHTML = `<i class="fas fa-city"></i> 前往其他城镇`; 
            charactersContainer.appendChild(ne);
        } else if (selectedCharacters.length > 0) { 
            selectedCharacters.forEach(character => { 
                const ce = document.createElement('div'); 
                ce.className = 'character-item'; 
                ce.innerHTML = `<i class="fas fa-user"></i> ${character}`; 
                charactersContainer.appendChild(ce); 
            }); 
        } else { 
            const ne = document.createElement('div'); 
            ne.className = 'character-item empty'; 
            ne.innerHTML = `<i class="fas fa-user-slash"></i> 这里没有人`; 
            charactersContainer.appendChild(ne); 
        }

        document.getElementById('location-details').classList.remove('hidden');
        // 清空自定义文本输入框
        document.getElementById('custom-message').value = '';
    }

    // Confirm move
    function confirmMove() {
        if (!selectedMain || !selectedSub) return; 

        const ln = `${selectedMain.name} - ${selectedSub.name}`; 

        const cm = document.getElementById('confirm-message');

        // 为悠谷村显示特殊确认信息
        if (isSpecialLocation) {
            cm.textContent = `前往 ${selectedSub.name}？这需要一些时间才能到达。`;
            // 隐藏购买按钮，因为对悠谷村不适用
            document.getElementById('purchase-move-btn').style.display = 'none';
        } else {
            const cs = selectedCharacters.join(', '); 
            cm.textContent = cs ? `前往 ${ln}？你可能会遇见：${cs}` : `前往 ${ln}？那里好像没有人。`;
            // 显示购买按钮
            document.getElementById('purchase-move-btn').style.display = 'block';
        }

        document.getElementById('confirm-overlay').classList.remove('hidden');
    }

    // Execute move - 特殊处理悠谷村移动请求
    function executeMove() {
        if (!selectedMain || !selectedSub) return;

        // 获取自定义文本
        const customMessage = document.getElementById('custom-message').value.trim();

        // 特殊处理悠谷村移动请求
        if (isSpecialLocation) {
            let m = `<request:{{user}}前往了悠谷村，${customMessage}<UpdateVariable> @变量.世界.当前位置=悠谷村@ </UpdateVariable>>`;

            if (typeof triggerSlash === 'function') {
                try {
                    triggerSlash(`/send ${m} || /trigger`);
                } catch (e) {
                    console.error("Error sending:", e);
                    alert("发送失败");
                }
            } else {
                console.warn("triggerSlash not found.");
                alert("移动请求已生成");
            }
        } else {
            // 常规移动请求
            const ln = `${selectedMain.name} - ${selectedSub.name}`;
            const c = selectedCharacters.join(',');
            let m = `<request:{{user}}前往了${ln}.${c ? c + '在那里' : ''}${customMessage ? '，' + customMessage : ''}>`;

            if (typeof triggerSlash === 'function') {
                try {
                    triggerSlash(`/send ${m} || /trigger`);
                } catch (e) {
                    console.error("Error sending:", e);
                    alert("发送失败");
                }
            } else {
                console.warn("triggerSlash not found.");
                alert("移动请求已生成");
            }
        }

        document.getElementById('confirm-overlay').classList.add('hidden');
    }

    // 执行购买移动 - 悠谷村不显示此按钮
    function executePurchaseMove() {
        if (!selectedMain || !selectedSub) return;

        // 常规购买请求
        const ln = `${selectedMain.name} - ${selectedSub.name}`;
        const c = selectedCharacters.join(',');
        // 获取自定义文本
        const customMessage = document.getElementById('custom-message').value.trim();
        // 购买请求消息，包含自定义文本
        let m = `<request:{{user}}前往了${ln}.${c ? c + '在那里' : ''}，{{user}}前往购买，如果有人正在工作告知可购买项目或物品${customMessage ? '，' + customMessage : ''}>`;

        if (typeof triggerSlash === 'function') {
            try {
                triggerSlash(`/send ${m} || /trigger`);
            } catch (e) {
                console.error("Error sending:", e);
                alert("发送失败");
            }
        } else {
            console.warn("triggerSlash not found.");
            alert("购买请求已生成");
        }

        document.getElementById('confirm-overlay').classList.add('hidden');
    }

    // Reset selection visuals
    function resetSelectionVisuals() {
        selectedMain = null; 
        selectedSub = null; 
        selectedCharacters = [];
        isSpecialLocation = false;

        document.querySelectorAll('.location-button.pixel-pressed, .sub-location-button.pixel-pressed').forEach(btn => { 
            btn.classList.remove('pixel-pressed'); 
        });

        document.getElementById('sub-locations').classList.add('hidden'); 
        document.getElementById('location-details').classList.add('hidden'); 
        document.getElementById('confirm-overlay').classList.add('hidden');
    }

    // Process map data from sources - 修改后的函数
    function processMapData() {
        const dataSource = document.getElementById('map-data-source');
        let mapText = dataSource.textContent || dataSource.innerText || '';

        try {
            if (window.parent && window.parent !== window) {
                // 查找父窗口中最近的消息内容
                const allMessages = window.parent.document.querySelectorAll('.mes_text, .mes_content, .message-content, .message_text');

                for (let i = allMessages.length - 1; i >= 0 && i >= allMessages.length - 10; i--) {
                    const messageText = allMessages[i].textContent || allMessages[i].innerText || '';

                    // 只处理包含地图数据格式的消息，排除明显是HTML或其他内容的消息
                    if (/\[\s*\n\s*-/s.test(messageText) && 
                        !messageText.includes('<!DOCTYPE html>') && 
                        !messageText.includes('<html>') &&
                        !messageText.includes('Set-Cookie:')) {

                        // 移除可能存在的移动阻止标记
                        mapText = messageText.replace(/\[MOVEBLOCK:(YES|NO)\]\s*\n?/i, '');
                        break;
                    }
                }
            }
        } catch (e) {
            console.warn("无法从父窗口获取消息:", e);
        }

        // 尝试从URL参数获取数据（作为备用）
        try {
            const urlParams = new URLSearchParams(window.location.search);
            const urlData = urlParams.get('data');

            if (urlData) {
                const decodedData = decodeURIComponent(urlData);
                if (/\[\s*\n\s*-/s.test(decodedData) && 
                    !decodedData.includes('<!DOCTYPE html>') && 
                    !decodedData.includes('<html>') &&
                    !decodedData.includes('Set-Cookie:')) {

                    mapText = decodedData.replace(/\[MOVEBLOCK:(YES|NO)\]\s*\n?/i, '');
                }
            }
        } catch (e) {
            console.warn("无法从URL获取数据:", e);
        }

        // 如果mapText为空或太短，使用备用数据
        if (!mapText || mapText.length < 10 || mapText.includes('Set-Cookie:')) {
            console.warn("获取到的地图数据无效，使用默认地图数据");
            mapText = "[]\n[]\n[]\n[]\n[]\n[]"; // 更新为6个空数组，匹配6个区域
        }

        // 解析地图数据并渲染
        currentMapData = parseMapData(mapText);
        if (currentMapData) {
            renderMapInterface(currentMapData);
        } else {
            console.error("地图数据处理失败");
        }
    }

    // Setup event listeners
    function setupEventListeners() {
        document.getElementById('confirm-move-btn').addEventListener('click', confirmMove);
        document.getElementById('cancel-move-btn').addEventListener('click', () => { 
            document.getElementById('confirm-overlay').classList.add('hidden'); 
        });
        document.getElementById('execute-move-btn').addEventListener('click', executeMove);
        // 添加购买按钮的事件监听器
        document.getElementById('purchase-move-btn').addEventListener('click', executePurchaseMove);
    }

    // Initialize
    function init() {
        setupEventListeners(); 
        processMapData(); 

        try { 
            if (window.parent && window.parent !== window && 
                typeof window.parent.eventOn === 'function' && 
                window.parent.tavern_events) { 

                let debounceTimer; 
                const debounceProcess = () => { 
                    clearTimeout(debounceTimer); 
                    debounceTimer = setTimeout(processMapData, 300); 
                }; 

                window.parent.eventOn(window.parent.tavern_events.MESSAGE_UPDATED, debounceProcess); 
                window.parent.eventOn(window.parent.tavern_events.MESSAGE_RECEIVED, debounceProcess); 
            } 
        } catch (e) { 
            console.warn("无法设置事件监听:", e); 
        }
    }

    document.addEventListener('DOMContentLoaded', init);
</script>

</body>
</html>
```

