---
# 世界书条目：Config - 全局状态检查
# 描述：获取当前位置，检查是否在特定地点（悠谷村、风临镇），并将结果定义为全局 config。
# 依赖扩展：提示词模板语法
# 重要：此条目必须在其他条件显示条目之前执行！

<%_
  // 1. 获取当前位置变量的值 (只获取一次！)
  const 当前位置 = getvar('变量.世界.当前位置'); // 假设用同一个变量记录所有位置

  // 2. 检查是否在各个地点
  const is悠谷村 = (当前位置 === '悠谷村');
  const is风临镇 = (当前位置 === '风临镇');

  // 3. 创建一个 config 对象来存放所有共享状态
  const config = {
    当前位置: 当前位置,     // 原始位置信息
    is悠谷村: is悠谷村,     // 是否在悠谷村
    is风临镇: is风临镇      // 是否在风临镇
  };

  // 4. 使用 define 将统一的 config 对象广播出去，供后续条目使用
  define('config', config);

  // 5. 这个条目本身不需要输出任何内容到提示词 (可选调试信息)
  // _%> <!-- Config: 当前='<%= config.当前位置 %>', 悠谷村='<%= config.is悠谷村 %>', 风临镇='<%= config.is风临镇 %>' --> <%_
_%>

---

